class Solution {
    public boolean judgeCircle(String moves){
        int x=0,y=0;
        for(char move:moves.toCharArray()){
            if(move=='U')y++;
            else if(move=='D')y--;
            else if(move=='L')x--;
            else x++;
        }
        return x==0&&y==0;
    }
}

code.kotlin:
class Solution {
    fun judgeCircle(moves:String):Boolean{
        var x=0;
        var y=0;
        for(move in moves)when(move){
            'U'->y++;
            'D'->y--;
            'L'->x--;
            else->x++
        };
        return x==0&&y==0
    }
}

code.cpp:
class Solution {
    public: bool judgeCircle(string moves){
        int x=0,y=0;
        for(char move:moves){
            if(move=='U')++y;
            else if(move=='D')--y;
            else if(move=='L')--x;
            else ++x;
        }
        return x==0&&y==0;
    }
};
